import React from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Link,
  Stack,
  Typography,
} from '@mui/material';
import OpenInNewIcon from '@mui/icons-material/OpenInNew';
import LinkIcon from '@mui/icons-material/Link';
import { ICM_PORTAL_FALLBACK_LINKS, type IcmPortalLink } from '../../constants/indianCarbonMarket';

export interface IcmRegistryAlignment {
  syncEnabled?: boolean;
  lastSyncStatus?: string;
  lastSyncedAt?: string | null;
  externalAccountId?: string | null;
  icmWorkflow?: {
    baselineSet?: boolean;
    baselineCo2Emissions?: number;
    latestReductionKgCO2?: number;
    totalQuantifiedCredits?: number;
  } | null;
  verificationUrl?: string;
  lastRetirementProof?: {
    serialNumber?: string;
    registryProjectId?: string;
    retirementCertificateUrl?: string;
  } | null;
}

export interface IcmIntegrationConfig {
  integrationMode?: string;
  configured?: boolean;
  portal?: { links?: IcmPortalLink[] };
  registryAlignment?: IcmRegistryAlignment;
}

interface IndianCarbonMarketPanelProps {
  integration?: IcmIntegrationConfig | null;
  compact?: boolean;
  showRegistryStatus?: boolean;
}

const IndianCarbonMarketPanel: React.FC<IndianCarbonMarketPanelProps> = ({
  integration,
  compact = false,
  showRegistryStatus = true,
}) => {
  const links = integration?.portal?.links?.length
    ? integration.portal.links
    : ICM_PORTAL_FALLBACK_LINKS;
  const alignment = integration?.registryAlignment;
  const mode = integration?.integrationMode || 'portal_links_only';
  const registryLive = integration?.configured === true;

  return (
    <Card variant="outlined" sx={{ mb: compact ? 2 : 3 }}>
      <CardContent>
        <Stack spacing={2}>
          <Box>
            <Typography variant={compact ? 'subtitle1' : 'h6'} gutterBottom>
              Indian Carbon Market (indiancarbonmarket.gov.in)
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Earned pool credits align with the national compliance market. Use the official portal
              for registration, issuance, and verification; this platform can sync when registry API
              access is enabled.
            </Typography>
          </Box>

          {showRegistryStatus && (
            <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
              <Chip
                size="small"
                label={registryLive ? 'Registry API connected' : 'Portal links only'}
                color={registryLive ? 'success' : 'default'}
                variant="outlined"
              />
              {alignment?.icmWorkflow?.baselineSet && (
                <Chip size="small" label="ICM baseline set" color="info" variant="outlined" />
              )}
              {alignment?.externalAccountId && (
                <Chip
                  size="small"
                  label={`Registry ID: ${alignment.externalAccountId}`}
                  variant="outlined"
                />
              )}
              {alignment?.lastSyncStatus && alignment.lastSyncStatus !== 'never' && (
                <Chip
                  size="small"
                  label={`Last sync: ${alignment.lastSyncStatus}`}
                  color={alignment.lastSyncStatus === 'success' ? 'success' : 'warning'}
                  variant="outlined"
                />
              )}
            </Stack>
          )}

          {mode === 'portal_links_only' && (
            <Alert severity="info" sx={{ py: 0.5 }}>
              Registry API is not configured. Credits are managed on-platform; link out to the
              national portal for official registration and certificate verification.
            </Alert>
          )}

          {alignment?.lastRetirementProof?.retirementCertificateUrl && (
            <Alert severity="success">
              Latest retirement certificate:{' '}
              <Link
                href={alignment.lastRetirementProof.retirementCertificateUrl}
                target="_blank"
                rel="noopener noreferrer"
              >
                View certificate
              </Link>
            </Alert>
          )}

          <Stack direction="row" flexWrap="wrap" gap={1}>
            {links.map((item) => (
              <Button
                key={item.id}
                component="a"
                href={item.url}
                target="_blank"
                rel="noopener noreferrer"
                size="small"
                variant="outlined"
                endIcon={<OpenInNewIcon fontSize="small" />}
              >
                {item.label}
              </Button>
            ))}
            {alignment?.verificationUrl && (
              <Button
                component="a"
                href={alignment.verificationUrl}
                target="_blank"
                rel="noopener noreferrer"
                size="small"
                variant="text"
                startIcon={<LinkIcon fontSize="small" />}
              >
                Verify on registry
              </Button>
            )}
          </Stack>
        </Stack>
      </CardContent>
    </Card>
  );
};

export default IndianCarbonMarketPanel;
